from scipy.optimize import least_squares
def nm(res): return np.mean(res**2)/np.var(dP_dt)
models={
'logistic_t_P': lambda p: (p[0]+p[1]*t+p[2]*np.sin(p[3]*t+p[4]))*P*(1-P/p[5]) + p[6]*0 ,
'sig_t_logis': lambda p: P*(p[0]/(1+p[1]*np.exp(-p[2]*t)))*(1-P/p[3]) + p[4]*np.log(P)*0,
'sig_t_additive': lambda p: p[0]*P*(1-P/p[1]) + p[2]/(1+np.exp(-p[3]*(t-p[4]))) + p[5]*P,
'sig_prod': lambda p: (p[0]+p[5]*P)/(1+np.exp(-p[1]*(t-p[2]))) + p[3]*P + p[4]*P*P,
}
rng=np.random.default_rng(0)
for name,f in models.items():
    best=None
    for trial in range(30):
        p0=rng.normal(size=7)*2
        try:
            r=least_squares(lambda p: f(p)-dP_dt, p0)
            if best is None or r.cost<best.cost: best=r
        except Exception as e: pass
    print(name, nm(best.fun), np.round(best.x,3))
